#include <nss.h>
#include <netdb.h>
#include <string.h>
#include <stdlib.h>
#include <arpa/inet.h>
#include <errno.h>

/* Minimal NSS module "prices": resolves prices.internal -> 127.0.0.1 (IPv4),
