static int is_ours(const char *name) {
    return name && strcmp(name, "prices.internal") == 0;
}

enum nss_status
_nss_prices_gethostbyname4_r(const char *name, struct gaih_addrtuple **pat,
                             char *buffer, size_t buflen, int *errnop,
                             int *herrnop, int32_t *ttlp)
{
    if (!is_ours(name)) return NSS_STATUS_NOTFOUND;
    if (buflen < sizeof(struct gaih_addrtuple) + 4 + strlen(name) + 1) {
        *errnop = ERANGE; *herrnop = NETDB_INTERNAL; return NSS_STATUS_TRYAGAIN;
    }
    struct gaih_addrtuple *t = (struct gaih_addrtuple *)buffer;
    memset(t, 0, sizeof(*t));
    t->name = buffer + sizeof(*t) + 4;
    strcpy(t->name, name);
    t->family = AF_INET;
    t->next = NULL;
    t->scopeid = 0;
    inet_pton(AF_INET, "127.0.0.1", buffer + sizeof(*t));
    memcpy(&t->addr, buffer + sizeof(*t), 4);
    *pat = t;
    return NSS_STATUS_SUCCESS;
}

static enum nss_status
fill_hostent(const char *name, struct hostent *host, char *buffer, size_t buflen,
             int *errnop, int *herrnop, int af)
{
    size_t need = sizeof(char*) * 2   /* aliases */
                + sizeof(char*) * 2   /* addr_list */
                + (af == AF_INET ? 4 : 16)
                + strlen(name) + 1;
    if (buflen < need) { *errnop = ERANGE; *herrnop = NETDB_INTERNAL; return NSS_STATUS_TRYAGAIN; }

    char *p = buffer;
    char **aliases = (char**)p; p += sizeof(char*) * 2;
    char **addrs   = (char**)p; p += sizeof(char*) * 2;
    char *addr     = p;         p += (af == AF_INET ? 4 : 16);
    char *nm       = p;

    strcpy(nm, name);
    aliases[0] = NULL;
    if (af == AF_INET) { inet_pton(AF_INET, "127.0.0.1", addr); }
    else               { inet_pton(AF_INET6, "::1", addr); }
    addrs[0] = addr; addrs[1] = NULL;

    host->h_name = nm;
    host->h_aliases = aliases;
    host->h_addrtype = af;
    host->h_length = (af == AF_INET ? 4 : 16);
    host->h_addr_list = addrs;
    return NSS_STATUS_SUCCESS;
}

enum nss_status
_nss_prices_gethostbyname3_r(const char *name, int af, struct hostent *host,
                             char *buffer, size_t buflen, int *errnop,
                             int *herrnop, int32_t *ttlp, char **canonp)
{
    if (!is_ours(name)) return NSS_STATUS_NOTFOUND;
    if (af != AF_INET && af != AF_INET6 && af != AF_UNSPEC) {
        *errnop = EAFNOSUPPORT; *herrnop = NETDB_INTERNAL; return NSS_STATUS_NOTFOUND;
